 { max-width: 82%; }
:where(.cb-bubble) {
  border-radius: 4px 16px 16px 16px; padding: 11px 15px;
  font-size: 15.5px; line-height: 22px; white-space: pre-wrap; word-break: break-word;
}
:where(.cb-bubble--client) { background: var(--cb-accent); color: #fff; border-radius: 16px 4px 16px 16px; }
:where(.cb-bubble--agent) { background: #fff; border: 1px solid #eee; color: #262626; }
:where(.cb-bubble--audio) { padding: 8px; }
:where(.cb-message-content:has(.prepared-message)) { width: 340px; min-width: 0; }
:where(.cb-bubble:has(.prepared-message)) { padding: 8px; white-space: normal; }
:where(.cb-message-time) { font-size: 11px; color: #bfbfbf; margin-top: 4px; margin-right: 4px; text-align: right; }
:where(.cb-composer, .cb-start-footer) { flex: none; background: #f7f8fa; border-top: 1px solid #e6e9ed; }
:where(.cb-composer) { --cb-composer-font-size: 15px; --cb-composer-line-height: 21px; padding: 8px 12px; }
:where(.cb-start-footer) { padding: 12px 14px 10px; }
:where(.cb-start-button) {
  width: 100%; height: 44px; border-radius: 10px; border: none;
  background: var(--cb-accent); color: #fff; font-size: 14px; font-weight: 600; cursor: pointer;
}
:where(.cb-composer-input) {
  flex: 1; min-width: 0; border: none; outline: none; resize: none; background: transparent;
  font-size: var(--cb-composer-font-size); line-height: var(--cb-composer-line-height); color: #262626; font-family: inherit;
  padding: 8px 2px; max-height: 132px;
}
:where(.cb-composer-button) {
  width: 32px; height: 32px; border-radius: 50%; border: none; background: transparent;
  display: flex; align-items: center; justify-content: center; cursor: pointer; flex: none; color: #8c8c8c;
}
:where(.cb-send-button) { background: var(--cb-accent); color: #fff; transition: background .18s ease; }
:where(.cb-send-button:disabled) { opacity: .6; }
:where(.cb-record-button) { background: #e6e9ed; color: #595959; }
:where(.cb-form) { margin: 2px 0 10px; max-width: 78%; background: #fff; border: 1px solid #eee; border-radius: 12px; padding: 12px; }
:where(.cb-form-field) {
  width: 100%; box-sizing: border-box; height: 38px; border-radius: 8px;
  border: 1px solid #d9d9d9; padding: 0 10px; outline: none; font-size: 13.5px;
}
:where(.cb-form-field[aria-invalid="true"]) { border-color: #ff4d4f; }
:where(.cb-form-submit) {
  width: 100%; height: 36px; margin-top: 8px; border-radius: 8px; border: none;
  background: var(--cb-accent); color: #fff; font-size: 12.5px; font-weight: 600; cursor: pointer;
}
:where(.cb-form-submit[data-valid="false"]) { background: #d9d9d9; cursor: default; }
:where(.cb-brand) { flex: none; background: #f7f8fa; padding: 7px 14px 10px; display: flex; justify-content: center; }
:where(.cb-widget) {
  --cb-text: #1f1f1f;
  --cb-field-text: #262626;
  --cb-label: #434343;
  --cb-secondary: #595959;
  --cb-muted: #8c8c8c;
  --cb-required: #cf1322;
  --cb-surface: #fff;
  --cb-site-surface: #fafafa;
  --cb-card-border: #f0f0f0;
  --cb-field-border: #d9d9d9;
}
:where(.cb-pre-chat) { display: flex; flex: 1; flex-direction: column; min-height: 0; }
:where(.cb-pre-chat-intro) {
  display: flex; flex-direction: column; align-items: center; text-align: center; padding: 6px 12px 4px;
}
:where(.cb-pre-chat-intro > span) { margin-bottom: 12px; }
:where(.cb-pre-chat-intro h3) { margin: 0; font-size: 17px; font-weight: 700; color: var(--cb-text); }
:where(.cb-pre-chat-intro p) {
  margin: 8px 0 0; font-size: 14.5px; line-height: 21px; color: var(--cb-secondary); max-width: 300px;
}
:where(.cb-pre-chat-card) {
  margin-top: 16px; background: var(--cb-surface); border: 1px solid var(--cb-card-border);
  border-radius: 12px; padding: 14px; display: flex; flex-direction: column; gap: 11px;
}
:where(.cb-pre-chat-label) {
  display: flex; align-items: center; gap: 6px; margin-bottom: 5px;
  font-size: 12.5px; font-weight: 600; color: var(--cb-label);
}
:where(.cb-pre-chat-required) { color: var(--cb-required); }
:where(.cb-pre-chat-source) { margin-left: auto; font-size: 11px; font-weight: 500; color: var(--cb-muted); }
:where(.cb-pre-chat-input) {
  width: 100%; box-sizing: border-box; height: 40px; border-radius: 8px;
  border: 1px solid var(--cb-field-border); padding: 0 11px; outline: none;
  font-size: 14px; font-family: inherit; color: var(--cb-field-text); background: var(--cb-surface);
}
:where(.cb-pre-chat-input[data-from-site="true"]) { background: var(--cb-site-surface); }
:where(.cb-pre-chat-consent) { margin-top: 12px; padding: 0 4px; }
:where(.cb-pre-chat .cb-start-button:disabled) { cursor: default; }
:where(.cb-consent) { font-size: 12px; color: var(--cb-secondary); line-height: 1.5; }
:where(.cb-consent a) { color: var(--cb-accent); font-weight: 600; text-decoration: none; }
:where(.cb-consent :is(b, strong)) { font-weight: 600; color: var(--cb-field-text); }
:where(.cb-consent :is(ul, ol)) { margin: 2px 0 0; padding-left: 18px; }
:where(.cb-consent p) { margin: 0; }
:where(.cb-consent-revision) { margin-top: 6px; color: var(--cb-muted); font-size: 11.5px; }
/* SPEC-0039 R-22: штатная типографика ввода, высота по содержимому. */
.wc-dictation-status { min-height:36px; display:flex; align-items:center; gap:8px; margin:0 0 4px; font-size:var(--cb-composer-font-size); line-height:var(--cb-composer-line-height); color:#595959; }
.wc-dictation-copy { flex:1; min-width:0; }
.wc-dictation-heading { display:flex; flex-wrap:wrap; align-items:center; gap:4px 8px; }
.wc-dictation-heading>svg,.wc-dictation-heading>strong { flex:none; }
.wc-dictation-heading>span { flex:1; min-width:0; overflow-wrap:anywhere; }
.wc-dictation-actions { display:flex; gap:4px; align-items:center; flex:none; }
.wc-dictation-timer { font-variant-numeric:tabular-nums; color:#cf1322; font-weight:600; }
.wc-dictation-stop { width:36px; height:36px; color:var(--cb-accent); }
.wc-dictation-trigger { margin-inline-end:4px; }
.wc-dictation-status.is-error { color:#cf1322; }
/* Accepted widget-speech player composition, using the existing voice classes. */
.wc-answer-audio{display:grid;grid-template-columns:minmax(0,1fr) 28px;gap:8px;align-items:end;margin-top:6px;white-space:normal}
.wc-answer-audio-toggle{grid-column:2;width:28px;height:28px;align-self:end}
.wc-answer-audio-toggle[aria-expanded=true]{color:var(--cb-accent)}
.wc-answer-player{min-width:0;margin-top:6px;font-size:12px}
.wc-answer-player .voice-message-player{display:flex;align-items:center;gap:10px}
.wc-answer-player .voice-message-play{width:36px;height:36px;flex:none;border:0;border-radius:50%;background:var(--cb-accent);color:#fff;display:inline-flex;align-items:center;justify-content:center;cursor:pointer}
.wc-answer-player .voice-message-play:disabled{cursor:wait}
.wc-answer-player .voice-message-wave{flex:1;display:flex;align-items:center;gap:2px;height:24px;min-width:0;overflow:hidden}
.wc-answer-player .voice-message-wave i{display:block;width:3px;border-radius:1.5px;background:#d9d9d9;flex:none}
.wc-answer-player .voice-message-wave i.is-played{background:var(--cb-accent)}
.wc-answer-player .voice-message-player em{flex:none;color:#8c8c8c;font-size:12px;font-weight:500;font-style:normal;font-variant-numeric:tabular-nums}
.wc-player-status{height:34px;display:flex;align-items:center;gap:8px;margin:6px 0 0;line-height:16px;color:#8c8c8c}
.wc-player-status>span{flex:1;min-width:0}
.wc-player-status.voice-message-error{color:#cf1322}
