.wc-answer-player .voice-message-wave i.is-played{background:var(--cb-accent)}
.wc-answer-player .voice-message-player em{flex:none;color:#8c8c8c;font-size:12px;font-weight:500;font-style:normal;font-variant-numeric:tabular-nums}
.wc-player-status{height:34px;display:flex;align-items:center;gap:8px;margin:6px 0 0;line-height:16px;color:#8c8c8c}
